1	/**
2	 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
3	 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
4	 */
5	
6	import { SANDBOX } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	
9	export function registrarConfigured(): boolean {
10	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
11	}
12	
13	/**
14	 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
15	 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
16	 * exercised end to end without touching the registrar or a real domain.
17	 */
18	export function transfersAvailable(): boolean {
19	  return SANDBOX || registrarConfigured();
20	}
21	
22	function baseUrl(): string {
23	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
24	}
25	
26	function authHeader(): string {
27	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
28	  return "Basic " + Buffer.from(raw).toString("base64");
29	}
30	
31	async function nc(
32	  method: string,
33	  path: string,
34	  body?: unknown,
35	  opts?: { nullOn404?: boolean }
36	): Promise<any> {
37	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
38	  const res = await fetch(`${baseUrl()}${path}`, {
39	    method,
40	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
41	    body: body ? JSON.stringify(body) : undefined,
42	    signal: AbortSignal.timeout(30_000),
43	  });
44	  const text = await res.text();
45	  let json: any = {};
46	  try {
47	    json = text ? JSON.parse(text) : {};
48	  } catch {
49	    /* non-JSON error body */
50	  }
51	  if (!res.ok) {
52	    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
53	    // that has already dropped off the registrar's list) — let them opt in to a
54	    // null instead of an exception rather than string-matching an error message.
55	    if (opts?.nullOn404 && res.status === 404) return null;
56	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
57	    throw new Error(`name.com: ${msg}`);
58	  }
59	  return json;
60	}
61	
62	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
63	
64	/** Fallback markup when no admin setting is saved. Matches the old hardcoded value. */
65	const DEFAULT_MARKUP_PCT = 25;
66	
67	/**
68	 * Platform markup over the registrar's cost, as a percentage.
69	 *
70	 * MONEY BUG (fixed 2026-07-26): Settings → Domains writes `domain_markup_percent`
71	 * and displays it, but NOTHING read it — the only references were the stored
72	 * default, the save whitelist, and the admin input itself. Meanwhile this function
73	 * read `DOMAIN_MARKUP_PCT`, which is not set in `.env`, so every domain price
74	 * silently carried the hardcoded 25%. The panel therefore showed an operator **0%**
75	 * while customers were charged **25%**, and editing the field changed nothing.
76	 *
77	 * The admin setting is now the source of truth, with the env var as the fallback so
78	 * an operator who had set it keeps their behaviour. The stored default is corrected
79	 * from "0" to 25 so the panel states what is genuinely applied — displaying 0% while
80	 * charging 25% is precisely the class of untruth this codebase keeps producing.
81	 *
82	 * Safe to change now: zero domains have been sold and the setting had never been
83	 * saved, so no customer's price moves as a result of this fix.
84	 *
85	 * Async because it reads a setting. Callers resolve it ONCE and pass it into
86	 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
87	 */
88	export async function domainMarkupPct(): Promise<number> {
89	  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
90	  const pct = await getSettingInt("domain_markup_percent", envDefault);
91	  // Clamp: a free-text admin field that multiplies every domain price. A stray
92	  // keystroke must not be able to bill a customer 5000% of cost.
93	  return Math.min(Math.max(Number.isFinite(pct) ? pct : envDefault, 0), 500);
94	}
95	
96	/** Retail (customer) price for a registrar cost at `pct` markup. Pure. */
97	export function retailCents(costCents: number | null, pct: number): number | null {
98	  if (costCents === null) return null;
99	  return Math.round(costCents * (1 + pct / 100));
100	}
101	
102	export type DomainCheck = {
103	  domain: string;
104	  available: boolean;
105	  premium: boolean;
106	  priceCents: number | null; // RETAIL — what the customer pays (per year)
107	  costCents: number | null; // registrar cost (per year)
108	  renewCents: number | null; // RETAIL renewal price
109	};
110	
111	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
112	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
113	  // Resolved ONCE for the whole batch: one settings read, and every price in a
114	  // single response is guaranteed to use the same markup.
115	  const pct = await domainMarkupPct();
116	  return (json.results ?? []).map((r: any) => {
117	    const cost = dollarsToCents(r.purchasePrice);
118	    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
119	    return {
120	      domain: r.domainName,
121	      available: r.purchasable === true,
122	      premium: r.premium === true,
123	      priceCents: retailCents(cost, pct),
124	      costCents: cost,
125	      renewCents: retailCents(renewCost, pct),
126	    };
127	  });
128	}
129	
130	export type RegistrantContact = {
131	  firstName: string;
132	  lastName: string;
133	  address1: string;
134	  city: string;
135	  stateProvince: string;
136	  postalCode: string;
137	  country: string; // ISO-2
138	  phone: string; // +NN.NNNNNNNNNN
139	  email: string;
140	};
141	
142	function ncContact(c: RegistrantContact) {
143	  return {
144	    firstName: c.firstName,
145	    lastName: c.lastName,
146	    address1: c.address1,
147	    city: c.city,
148	    state: c.stateProvince,
149	    zip: c.postalCode,
150	    country: c.country,
151	    phone: c.phone,
152	    email: c.email,
153	  };
154	}
155	
156	/**
157	 * name.com's OWN auto-renew flag on the domain resource — entirely separate
158	 * from this platform's `Domain.autoRenew` column, and NOT settable on the
159	 * CreateDomain request itself (confirmed against name.com's own API docs).
160	 * Real risk found live (2026-08-29): if name.com's own default for an
161	 * API-registered domain is enabled, name.com can independently renew (and
162	 * charge NXEON'S reseller account, not the customer) on ITS OWN schedule —
163	 * regardless of what the customer chose here, including a domain they
164	 * explicitly turned auto-renew off for, or one whose owner has no wallet
165	 * funds. Disabling it after every register/renew makes
166	 * worker/billing.ts's domainAutoRenewSweep the ONLY thing that ever
167	 * initiates a renewal. Best-effort: must never fail a registration/renewal
168	 * that already succeeded and was already charged — a dangling
169	 * autorenew-enabled domain is a real ops risk to catch via this log line,
170	 * not a reason to unwind money that already moved.
171	 */
172	async function disableRegistrarAutorenew(domain: string): Promise<void> {
173	  try {
174	    await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:disableAutorenew`);
175	  } catch (e) {
176	    console.error(`[registrar] failed to disable name.com's own auto-renew for ${domain} — it may renew/charge independently of our sweep`, e);
177	  }
178	}
179	
180	/** Registers for `years` at the given expected price (from checkDomains). */
181	export async function registerDomain(
182	  domain: string,
183	  years: number,
184	  contact: RegistrantContact,
185	  purchaseCents: number
186	): Promise<{ expiresAt?: Date }> {
187	  const c = ncContact(contact);
188	  const json = await nc("POST", "/v4/domains", {
189	    domain: {
190	      domainName: domain,
191	      contacts: { registrant: c, admin: c, tech: c, billing: c },
192	      privacyEnabled: true,
193	    },
194	    purchasePrice: purchaseCents / 100,
195	    years,
196	  });
197	  await disableRegistrarAutorenew(domain);
198	  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
199	  return { expiresAt: exp ? new Date(exp) : undefined };
200	}
201	
202	export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
203	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
204	    purchasePrice: purchaseCents / 100,
205	    years,
206	  });
207	  await disableRegistrarAutorenew(domain);
208	}
209	
210	export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
211	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
212	  return {
213	    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
214	    created: json?.createDate ? new Date(json.createDate) : undefined,
215	  };
216	}
217	
218	// ---------- Inbound transfers (transfer-in) ----------
219	//
220	// name.com v4 transfers:
221	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
222	//   GET  /v4/transfers                      -> { transfers: [...] }
223	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
224	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
225	//
226	// A transfer always includes a 1-year extension of the registration, which is
227	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
228	// registration rate.
229	
230	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
231	const SANDBOX_APPROVAL_MS = 2 * 60_000;
232	const SANDBOX_REGISTRY_MS = 5 * 60_000;
233	
234	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
235	function sandboxTldCostCents(domain: string): number {
236	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
237	  let h = 0;
238	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
239	  return 900 + (h % 21) * 50; // $9.00 – $19.00
240	}
241	
242	export type TransferCheck = {
243	  domain: string;
244	  /** True when we believe an inbound transfer can be submitted for this name. */
245	  transferable: boolean;
246	  /** Plain-English reason when `transferable` is false. */
247	  reason: string | null;
248	  premium: boolean;
249	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
250	  priceCents: number | null;
251	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
252	  costCents: number | null;
253	};
254	
255	/**
256	 * The registrar cost of transferring `domain`, in integer cents.
257	 *
258	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
259	 * a name it can see, so we try three sources in order and give up honestly:
260	 *   1. the availability result for the domain itself,
261	 *   2. the per-domain pricing endpoint,
262	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
263	 *      unregistered sibling quotes the same renewal rate.
264	 */
265	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
266	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
267	  if (own !== null && own > 0) return own;
268	
269	  try {
270	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
271	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
272	    if (quoted !== null && quoted > 0) return quoted;
273	  } catch {
274	    /* endpoint unavailable for this TLD/account — fall through to the probe */
275	  }
276	
277	  const tld = domain.slice(domain.indexOf(".") + 1);
278	  try {
279	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
280	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
281	    const r = (json.results ?? [])[0];
282	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
283	    if (c !== null && c > 0) return c;
284	  } catch {
285	    /* registrar unhappy — no price, caller surfaces that plainly */
286	  }
287	  return null;
288	}
289	
290	/**
291	 * Can this domain be transferred in, and what would it cost? Never throws for a
292	 * "no" answer — a non-transferable name comes back with `transferable: false`
293	 * and a reason the customer can act on.
294	 */
295	export async function checkTransfer(domain: string): Promise<TransferCheck> {
296	  if (SANDBOX) {
297	    // Synthetic: everything is transferable except names containing "locked",
298	    // which exercise the rejected-quote path in staging.
299	    const cost = sandboxTldCostCents(domain);
300	    if (domain.includes("locked")) {
301	      return {
302	        domain,
303	        transferable: false,
304	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
305	        premium: false,
306	        priceCents: null,
307	        costCents: null,
308	      };
309	    }
310	    return {
311	      domain,
312	      transferable: true,
313	      reason: null,
314	      premium: false,
315	      priceCents: retailCents(cost, await domainMarkupPct()),
316	      costCents: cost,
317	    };
318	  }
319	
320	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
321	  const r = (json.results ?? [])[0];
322	  if (!r) {
323	    return {
324	      domain,
325	      transferable: false,
326	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
327	      premium: false,
328	      priceCents: null,
329	      costCents: null,
330	    };
331	  }
332	  // Purchasable means nobody owns it — there is nothing to transfer.
333	  if (r.purchasable === true) {
334	    return {
335	      domain,
336	      transferable: false,
337	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
338	      premium: r.premium === true,
339	      priceCents: null,
340	      costCents: null,
341	    };
342	  }
343	  if (r.premium === true) {
344	    return {
345	      domain,
346	      transferable: false,
347	      reason: "Premium domains can't be transferred in automatically — contact support.",
348	      premium: true,
349	      priceCents: null,
350	      costCents: null,
351	    };
352	  }
353	
354	  const cost = await transferCostCents(domain, r);
355	  if (cost === null) {
356	    return {
357	      domain,
358	      transferable: false,
359	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
360	      premium: false,
361	      priceCents: null,
362	      costCents: null,
363	    };
364	  }
365	  return {
366	    domain,
367	    transferable: true,
368	    reason: null,
369	    premium: false,
370	    priceCents: retailCents(cost, await domainMarkupPct()),
371	    costCents: cost,
372	  };
373	}
374	
375	export type TransferInfo = {
376	  domain: string;
377	  /** Raw registrar status, shown to the customer verbatim. */
378	  status: string;
379	  /** Where the losing registrar sent the approval email (not every TLD sends one). */
380	  email: string | null;
381	};
382	
383	/**
384	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
385	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
386	 * The auth code is passed straight through and never logged.
387	 */
388	export async function createTransfer(
389	  domain: string,
390	  authCode: string,
391	  purchaseCents: number
392	): Promise<TransferInfo> {
393	  if (SANDBOX) {
394	    // Names containing "fail" reject at submit time so staging can exercise the
395	    // "registrar refused, customer not charged" path.
396	    if (domain.includes("fail")) throw new Error("name.com: transfer rejected by the registry (sandbox)");
397	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
398	  }
399	  const json = await nc("POST", "/v4/transfers", {
400	    domainName: domain,
401	    authCode,
402	    privacyEnabled: true,
403	    purchasePrice: purchaseCents / 100,
404	  });
405	  const t = json?.transfer ?? json ?? {};
406	  return {
407	    domain: t.domainName ?? domain,
408	    status: String(t.status ?? "pending"),
409	    email: t.email ? String(t.email) : null,
410	  };
411	}
412	
413	/**
414	 * Current state of an inbound transfer. Returns null when the registrar has no
415	 * transfer for this domain — which is a NORMAL answer once a transfer settles
416	 * and drops off the list, so callers must resolve that against `domainInfo`
417	 * rather than treating it as a failure.
418	 *
419	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
420	 * (registrar.ts holds no state of its own).
421	 */
422	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
423	  if (SANDBOX) {
424	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
425	    const status =
426	      age < SANDBOX_APPROVAL_MS
427	        ? "pendingOwnerApproval"
428	        : age < SANDBOX_REGISTRY_MS
429	          ? "pendingRegistry"
430	          : "completed";
431	    return { domain, status, email: `owner@${domain}` };
432	  }
433	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
434	  if (!t) return null;
435	  return {
436	    domain: t.domainName ?? domain,
437	    status: String(t.status ?? "pending"),
438	    email: t.email ? String(t.email) : null,
439	  };
440	}
441	
442	/**
443	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
444	 * registrar refuses (e.g. the transfer already completed at the registry) —
445	 * callers must NOT credit the customer unless this resolves.
446	 */
447	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
448	  if (SANDBOX) return { domain, status: "cancelled", email: null };
449	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
450	  return {
451	    domain: t?.domainName ?? domain,
452	    status: String(t?.status ?? "cancelled"),
453	    email: t?.email ? String(t.email) : null,
454	  };
455	}
456	
457	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
458	export async function listTransfers(): Promise<TransferInfo[]> {
459	  if (SANDBOX) return [];
460	  const json = await nc("GET", "/v4/transfers");
461	  return (json.transfers ?? []).map((t: any) => ({
462	    domain: t.domainName,
463	    status: String(t.status ?? "pending"),
464	    email: t.email ? String(t.email) : null,
465	  }));
466	}
467	
468	/** Bucket a raw registrar transfer status into something we can act on. */
469	export function transferOutcome(status: string): "completed" | "failed" | "pending" {
470	  const s = status.toLowerCase();
471	  if (/(complete|success|transferred)/.test(s)) return "completed";
472	  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
473	  return "pending";
474	}
475	
476	/** Human label for a raw registrar transfer status. */
477	export function transferStatusLabel(status: string): string {
478	  const s = status.toLowerCase();
479	  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
480	  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
481	  if (/complete|success|transferred/.test(s)) return "Completed";
482	  if (/cancel/.test(s)) return "Cancelled";
483	  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
484	  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
485	  return status;
486	}
