490	export type DnsRecord = {
491	  id: number;
492	  host: string; // "" = apex
493	  type: string;
494	  answer: string;
495	  ttl: number;
496	  priority?: number;
497	};
498	
499	export async function listRecords(domain: string): Promise<DnsRecord[]> {
500	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
501	  return (json.records ?? []).map((r: any) => ({
502	    id: r.id,
503	    host: r.host ?? "",
504	    type: r.type,
505	    answer: r.answer,
506	    ttl: r.ttl ?? 300,
507	    priority: r.priority,
508	  }));
509	}
510	
511	export async function addRecord(
512	  domain: string,
513	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
514	): Promise<void> {
515	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
516	    host: rec.host,
517	    type: rec.type,
518	    answer: rec.answer,
519	    ttl: rec.ttl ?? 300,
520	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
521	  });
522	}
523	
524	export async function deleteRecord(domain: string, id: number): Promise<void> {
525	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
526	}
527	
528	/** Read-only view used by the DNS UI: apex host shown as "@". */
529	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
530	
531	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
532	  const recs = await listRecords(domain);
533	  return recs.map((r) => ({
534	    name: r.host === "" ? "@" : r.host,
535	    type: r.type,
536	    address: r.answer,
537	    ttl: r.ttl,
538	    mxPref: r.priority,
539	  }));
540	}
