1	/**
2	 * Batched, cached, globally-throttled availability lookups for the public
3	 * domain-name generator.
4	 *
5	 * The registrar (name.com, via `lib/registrar.ts`) is a METERED third-party API
6	 * on a public unauthenticated endpoint, so three protections sit in front of it:
7	 *
8	 *   1. CACHE     — a short-TTL in-process map keyed by domain. Repeat lookups
9	 *                  (same visitor re-rolling, two visitors with the same brief,
10	 *                  popular industry pages) cost nothing.
11	 *   2. BATCHING  — name.com's `domains:checkAvailability` takes an array, so a
12	 *                  whole page of candidates is ONE upstream call. Verified at
13	 *                  25 names/call in ~0.9s.
14	 *   3. GLOBAL CAP — a process-wide sliding window on top of the per-IP limit in
15	 *                  the route, so a botnet spread across many IPs still cannot
16	 *                  push unbounded volume at the registrar.
17	 *
18	 * Prices are only ever what the registrar returned. When the API gives us no
19	 * price we surface no price — never an estimate, never a TLD average.
20	 */
21	
22	import { checkRateLimit } from "@/lib/rate-limit";
23	import { checkDomains, registrarConfigured, type DomainCheck } from "@/lib/registrar";
24	
25	/** Max domains sent in a single upstream call. Verified working at 25. */
26	const BATCH_SIZE = 24;
27	
28	/** Cache lifetime. Long enough to absorb re-rolls, short enough to stay honest. */
29	const CACHE_TTL_MS = 10 * 60 * 1000;
30	
31	/** Hard ceiling on entries so the map can't grow unbounded. */
32	const CACHE_MAX = 4000;
33	
34	/** Process-wide registrar budget: batches per minute across ALL visitors. */
35	const GLOBAL_BATCHES_PER_MIN = 60;
36	
37	type Entry = { at: number; check: DomainCheck };
38	
39	const localCache = new Map<string, Entry>();
40	// Survive HMR / route reloads in dev so the cache actually caches.
41	const globalForCache = globalThis as unknown as { __nxeonDomainAvail?: Map<string, Entry> };
42	const cache: Map<string, Entry> = globalForCache.__nxeonDomainAvail ?? localCache;
43	if (process.env.NODE_ENV !== "production") globalForCache.__nxeonDomainAvail = cache;
44	
45	function readCache(domain: string, now: number): DomainCheck | null {
46	  const hit = cache.get(domain);
47	  if (!hit) return null;
48	  if (now - hit.at > CACHE_TTL_MS) {
49	    cache.delete(domain);
50	    return null;
51	  }
52	  return hit.check;
53	}
54	
55	function writeCache(check: DomainCheck, now: number): void {
56	  if (cache.size >= CACHE_MAX) {
57	    // Drop the oldest ~10% rather than clearing everything on a cold spike.
58	    const victims = [...cache.entries()]
59	      .sort((a, b) => a[1].at - b[1].at)
60	      .slice(0, Math.ceil(CACHE_MAX / 10));
61	    for (const [k] of victims) cache.delete(k);
62	  }
63	  cache.set(check.domain, { at: now, check });
64	}
65	
66	export type AvailabilityStatus = "available" | "taken" | "unknown";
67	
68	export type DomainResult = {
69	  domain: string;
70	  status: AvailabilityStatus;
71	  premium: boolean;
72	  /** Retail first-year price in integer cents, or null when the registrar gave none. */
73	  priceCents: number | null;
74	  /** Retail renewal price in integer cents, or null. */
75	  renewCents: number | null;
76	};
77	
78	export type AvailabilityOutcome = {
79	  results: DomainResult[];
80	  /** False when the registrar isn't configured at all — everything is "unknown". */
81	  configured: boolean;
82	  /** True when we skipped the registrar to protect the shared upstream budget. */
83	  throttled: boolean;
84	  /** How many domains were served from cache rather than the registrar. */
85	  cached: number;
86	};
87	
88	function toResult(check: DomainCheck): DomainResult {
89	  // name.com only prices a purchasable name; a taken domain comes back priceless.
90	  const available = check.available && check.priceCents !== null;
91	  return {
92	    domain: check.domain,
93	    status: available ? "available" : "taken",
94	    premium: check.premium,
95	    priceCents: available ? check.priceCents : null,
96	    renewCents: available ? check.renewCents : null,
97	  };
98	}
99	
100	function unknown(domain: string): DomainResult {
101	  return { domain, status: "unknown", premium: false, priceCents: null, renewCents: null };
102	}
103	
104	/**
105	 * Look up availability for a list of domains, preserving input order.
106	 *
107	 * Never throws: a registrar outage degrades every uncached domain to `unknown`
108	 * so the page still renders names, clearly marked as unverified.
109	 */
110	export async function checkAvailabilityBatched(domains: string[]): Promise<AvailabilityOutcome> {
111	  const now = Date.now();
112	  const unique = [...new Set(domains.map((d) => d.toLowerCase()))];
113	
114	  if (!registrarConfigured()) {
115	    return { results: unique.map(unknown), configured: false, throttled: false, cached: 0 };
116	  }
117	
118	  const resolved = new Map<string, DomainResult>();
119	  const misses: string[] = [];
120	  for (const d of unique) {
121	    const hit = readCache(d, now);
122	    if (hit) resolved.set(d, toResult(hit));
123	    else misses.push(d);
124	  }
125	  const cached = resolved.size;
126	
127	  let throttled = false;
128	  const batches: string[][] = [];
129	  for (let i = 0; i < misses.length; i += BATCH_SIZE) batches.push(misses.slice(i, i + BATCH_SIZE));
130	
131	  for (const batch of batches) {
132	    // Shared upstream budget — checked per batch, not per domain.
133	    const budget = checkRateLimit("registrar:availability:global", {
134	      max: GLOBAL_BATCHES_PER_MIN,
135	      windowMs: 60_000,
136	    });
137	    if (!budget.ok) {
138	      throttled = true;
139	      for (const d of batch) resolved.set(d, unknown(d));
140	      continue;
141	    }
142	
143	    try {
144	      const checks = await checkDomains(batch);
145	      const seen = new Set<string>();
146	      for (const check of checks) {
147	        const key = check.domain.toLowerCase();
148	        seen.add(key);
149	        writeCache({ ...check, domain: key }, now);
150	        resolved.set(key, toResult(check));
151	      }
152	      // A domain the registrar simply didn't answer for stays honest.
153	      for (const d of batch) if (!seen.has(d)) resolved.set(d, unknown(d));
154	    } catch {
155	      for (const d of batch) resolved.set(d, unknown(d));
156	    }
157	  }
158	
159	  return {
160	    results: unique.map((d) => resolved.get(d) ?? unknown(d)),
161	    configured: true,
162	    throttled,
163	    cached,
164	  };
165	}
166	
167	/** `$12.99` from integer cents. Returns null so callers can't print a fake price. */
168	export function formatPrice(cents: number | null): string | null {
169	  if (cents === null || !Number.isFinite(cents)) return null;
170	  return `$${(cents / 100).toFixed(2)}`;
171	}
