15	/* ------------------------------------------------------------------ *
16	 * DNS super-manager actions for the customer domain manager.
17	 *
18	 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
19	 * deleteRecord) for all record mutations. name.com endpoints not exposed
20	 * by that helper (URL forwarding, registrar lock) are called directly via
21	 * a minimal Basic-auth client that mirrors lib/registrar.ts, exactly like
22	 * lib/actions-domains-advanced.ts does. Everything is ownership-checked and
23	 * degrades gracefully (persist intent + a clear note) when the registrar
24	 * isn't configured or a TLD/endpoint isn't supported.
25	 * ------------------------------------------------------------------ */
26	
27	function baseUrl(): string {
28	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
29	}
30	
31	function authHeader(): string {
32	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
33	  return "Basic " + Buffer.from(raw).toString("base64");
34	}
35	
36	async function nc(method: string, path: string, body?: unknown): Promise<any> {
37	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
38	  const res = await fetch(`${baseUrl()}${path}`, {
39	    method,
40	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
41	    body: body !== undefined ? JSON.stringify(body) : undefined,
42	    signal: AbortSignal.timeout(30_000),
43	  });
44	  const text = await res.text();
45	  let json: any = {};
46	  try {
47	    json = text ? JSON.parse(text) : {};
48	  } catch {
49	    /* non-JSON error body */
50	  }
51	  if (!res.ok) {
52	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
53	    throw new Error(`name.com: ${msg}`);
54	  }
55	  return json;
56	}
57	
58	function errMsg(e: unknown): string {
59	  return String(e instanceof Error ? e.message : e).slice(0, 200);
60	}
61	
62	async function ownedDomain(domainId: string) {
63	  const user = await requireUser();
64	  const domain = await db.domain.findUnique({ where: { id: domainId } });
65	  if (!domain) throw new Error("Not found");
66	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
67	  return { user, domain };
